from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Parity (0 or 1) of each element of xs, computed in parallel with a
    thread pool. The result is in input order, independent of worker count
    or task completion order."""
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4]) == [0, 1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2, -3]) == [1, 0, 1]


def test_parities_large_ints() -> None:
    assert parities([2**100, 2**100 + 1]) == [0, 1]


@pytest.mark.parametrize("n", [1, 2, 7, 100, 1000])
def test_parities_matches_sequential(n: int) -> None:
    xs = [(i * 7919) % 1009 - 500 for i in range(n)]
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_order_is_input_order() -> None:
    xs = [1] * 50 + [0] * 50 + [1, 0] * 25
    assert parities(xs) == xs


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 4, 3]
    parities(xs)
    assert xs == [5, 4, 3]


def test_parities_returns_new_list() -> None:
    xs = [0, 1]
    assert parities(xs) is not xs


def test_parities_repeatable() -> None:
    xs = list(range(500))
    first = parities(xs)
    assert all(parities(xs) == first for _ in range(5))
